-- RESTORA initial schema. Apply with Supabase CLI or SQL Editor.
create extension if not exists pgcrypto;
create type public.member_role as enum ('restaurant_owner','manager','kitchen_staff','waiter','customer');
create type public.application_status as enum ('pending','approved','rejected');
create type public.restaurant_status as enum ('pending','active','suspended','rejected');
create type public.order_status as enum ('pending','confirmed','preparing','ready','completed','cancelled');
create type public.payment_status as enum ('pending','authorized','paid','failed','refunded');
create type public.reservation_status as enum ('pending','confirmed','seated','cancelled','completed');

create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$begin new.updated_at=now();return new;end$$;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', phone text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.super_admins(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.restaurants(id uuid primary key default gen_random_uuid(),name text not null,status public.restaurant_status not null default 'pending',description text,cuisine_type text,address text,phone text,email text,logo_url text,cover_url text,opening_hours jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.restaurant_applications(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,restaurant_id uuid references public.restaurants(id) on delete set null,restaurant_name text not null,owner_name text not null,email text not null,phone text,address text not null,cuisine_type text,description text,status public.application_status not null default 'pending',reviewed_by uuid references public.super_admins(user_id),reviewed_at timestamptz,rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.restaurant_memberships(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.member_role not null,active boolean not null default true,permissions jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(restaurant_id,user_id));
create table public.subscription_plans(id uuid primary key default gen_random_uuid(),name text unique not null,price numeric(10,2) not null default 0 check(price>=0),billing_period text not null default 'monthly' check(billing_period in ('monthly','yearly')),features jsonb not null default '[]',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,plan_id uuid not null references public.subscription_plans(id),status text not null default 'active' check(status in ('active','inactive','expired','cancelled')),starts_at timestamptz not null default now(),expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null,description text,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(restaurant_id,name));
create table public.products(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,category_id uuid references public.categories(id) on delete set null,name text not null,description text,price numeric(10,2) not null check(price>=0),image_url text,available boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_variants(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,name text not null,price_delta numeric(10,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.restaurant_tables(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,table_number text not null,capacity int not null default 2 check(capacity>0),status text not null default 'available' check(status in ('available','occupied','reserved')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(restaurant_id,table_number));
create table public.orders(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,customer_id uuid references auth.users(id) on delete set null,created_by uuid references auth.users(id),table_id uuid references public.restaurant_tables(id),order_type text not null default 'takeaway' check(order_type in ('dine_in','takeaway','delivery')),status public.order_status not null default 'pending',subtotal numeric(10,2) not null default 0 check(subtotal>=0),tax numeric(10,2) not null default 0 check(tax>=0),total numeric(10,2) not null default 0 check(total>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,name_snapshot text not null,quantity int not null check(quantity>0),unit_price numeric(10,2) not null check(unit_price>=0),variant text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,order_id uuid not null references public.orders(id) on delete cascade,method text not null check(method in ('cash_on_delivery','cash_at_restaurant','online')),status public.payment_status not null default 'pending',amount numeric(10,2) not null check(amount>=0),provider text,provider_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.reservations(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,customer_id uuid not null references auth.users(id) on delete cascade,table_id uuid references public.restaurant_tables(id) on delete set null,party_size int not null check(party_size>0),reserved_for timestamptz not null,status public.reservation_status not null default 'pending',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.inventory_items(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null,quantity numeric(12,3) not null default 0,unit text not null default 'unit',low_stock_threshold numeric(12,3) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(restaurant_id,name));
create table public.inventory_transactions(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,item_id uuid not null references public.inventory_items(id) on delete cascade,quantity_delta numeric(12,3) not null,reason text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,customer_id uuid not null references auth.users(id) on delete cascade,order_id uuid references public.orders(id) on delete set null,rating int not null check(rating between 1 and 5),comment text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(customer_id,order_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),restaurant_id uuid references public.restaurants(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,title text not null,body text,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),restaurant_id uuid references public.restaurants(id) on delete set null,actor_id uuid references auth.users(id) on delete set null,action text not null,entity text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create index on public.restaurant_memberships(user_id,active);create index on public.restaurant_memberships(restaurant_id,role);create index on public.restaurant_applications(status,created_at desc);create index on public.orders(restaurant_id,status,created_at desc);create index on public.orders(customer_id,created_at desc);create index on public.products(restaurant_id,category_id,available);create index on public.reservations(restaurant_id,reserved_for);create index on public.notifications(user_id,created_at desc);

create or replace function public.on_auth_user_created() returns trigger language plpgsql security definer set search_path=public,auth as $$begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.raw_user_meta_data->>'phone') on conflict(id) do nothing;if nullif(new.raw_user_meta_data->>'restaurant_name','') is not null then insert into public.restaurant_applications(owner_id,restaurant_name,owner_name,email,phone,address,cuisine_type,status) values(new.id,new.raw_user_meta_data->>'restaurant_name',coalesce(new.raw_user_meta_data->>'owner_name',''),new.email,new.raw_user_meta_data->>'phone',coalesce(new.raw_user_meta_data->>'address',''),new.raw_user_meta_data->>'cuisine_type','pending');end if;return new;end$$;
create trigger auth_user_profile after insert on auth.users for each row execute function public.on_auth_user_created();
do $$declare t text;begin foreach t in array array['profiles','restaurants','restaurant_applications','restaurant_memberships','subscription_plans','subscriptions','categories','products','product_variants','restaurant_tables','orders','order_items','payments','reservations','inventory_items','reviews'] loop execute format('create trigger %I_updated before update on public.%I for each row execute function public.set_updated_at()',t,t);end loop;end$$;

create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.super_admins where user_id=auth.uid())$$;
create or replace function public.has_restaurant_access(rid uuid, allowed public.member_role[] default null) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.restaurant_memberships m join public.restaurants r on r.id=m.restaurant_id where m.user_id=auth.uid() and m.restaurant_id=rid and m.active and r.status='active' and (allowed is null or m.role=any(allowed)))$$;
revoke all on function public.is_super_admin() from public;grant execute on function public.is_super_admin() to anon,authenticated;
revoke all on function public.has_restaurant_access(uuid,public.member_role[]) from public;grant execute on function public.has_restaurant_access(uuid,public.member_role[]) to anon,authenticated;

create or replace function public.review_restaurant_application(app_id uuid, approve boolean, reason text default null) returns uuid language plpgsql security definer set search_path=public as $$declare a public.restaurant_applications;rid uuid;begin if not public.is_super_admin() then raise exception 'super admin required';end if;select * into a from public.restaurant_applications where id=app_id for update;if not found or a.status<>'pending' then raise exception 'application not found or already reviewed';end if;if approve then insert into public.restaurants(name,status,phone,email,address,cuisine_type,description) values(a.restaurant_name,'active',a.phone,a.email,a.address,a.cuisine_type,a.description) returning id into rid;insert into public.restaurant_memberships(restaurant_id,user_id,role) values(rid,a.owner_id,'restaurant_owner') on conflict(restaurant_id,user_id) do update set active=true,role='restaurant_owner';insert into public.subscriptions(restaurant_id,plan_id) select rid,id from public.subscription_plans where name='Free' limit 1;update public.restaurant_applications set status='approved',restaurant_id=rid,reviewed_by=auth.uid(),reviewed_at=now() where id=app_id;else update public.restaurant_applications set status='rejected',rejection_reason=reason,reviewed_by=auth.uid(),reviewed_at=now() where id=app_id;end if;return rid;end$$;
revoke all on function public.review_restaurant_application(uuid,boolean,text) from public;grant execute on function public.review_restaurant_application(uuid,boolean,text) to authenticated;

-- Checkout prices are calculated from the live menu inside PostgreSQL.
create or replace function public.place_order(rid uuid, items jsonb, kind text default 'takeaway', pay_method text default 'cash_at_restaurant') returns uuid language plpgsql security definer set search_path=public as $$declare oid uuid;item jsonb;p public.products;q int;subtotal numeric(10,2):=0;begin if auth.uid() is null then raise exception 'authentication required';end if;if kind not in ('dine_in','takeaway','delivery') then raise exception 'invalid order type';end if;if pay_method not in ('cash_on_delivery','cash_at_restaurant','online') then raise exception 'invalid payment method';end if;if not exists(select 1 from public.restaurants where id=rid and status='active') then raise exception 'restaurant is unavailable';end if;if jsonb_typeof(items)<>'array' or jsonb_array_length(items)=0 then raise exception 'order must contain items';end if;for item in select * from jsonb_array_elements(items) loop q:=(item->>'quantity')::int;if q<1 or q>50 then raise exception 'invalid quantity';end if;select * into p from public.products where id=(item->>'product_id')::uuid and restaurant_id=rid and available;if not found then raise exception 'menu item is unavailable';end if;subtotal:=subtotal+p.price*q;end loop;insert into public.orders(restaurant_id,customer_id,order_type,status,subtotal,total) values(rid,auth.uid(),kind,'pending',subtotal,subtotal) returning id into oid;for item in select * from jsonb_array_elements(items) loop q:=(item->>'quantity')::int;select * into p from public.products where id=(item->>'product_id')::uuid and restaurant_id=rid and available;insert into public.order_items(restaurant_id,order_id,product_id,name_snapshot,quantity,unit_price,variant) values(rid,oid,p.id,p.name,q,p.price,nullif(item->>'variant',''));end loop;insert into public.payments(restaurant_id,order_id,method,status,amount) values(rid,oid,pay_method,'pending',subtotal);return oid;end$$;
revoke all on function public.place_order(uuid,jsonb,text,text) from public;grant execute on function public.place_order(uuid,jsonb,text,text) to authenticated;
create or replace function public.apply_inventory_delta() returns trigger language plpgsql security definer set search_path=public as $$begin update public.inventory_items set quantity=quantity+new.quantity_delta where id=new.item_id and restaurant_id=new.restaurant_id;if not found then raise exception 'inventory item not found in this restaurant';end if;return new;end$$;
create trigger inventory_transaction_apply after insert on public.inventory_transactions for each row execute function public.apply_inventory_delta();

-- Prevent public role escalation and keep every tenant-scoped table within membership boundaries.
alter table public.profiles enable row level security;alter table public.super_admins enable row level security;alter table public.restaurants enable row level security;alter table public.restaurant_applications enable row level security;alter table public.restaurant_memberships enable row level security;alter table public.subscription_plans enable row level security;alter table public.subscriptions enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.product_variants enable row level security;alter table public.restaurant_tables enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.payments enable row level security;alter table public.reservations enable row level security;alter table public.inventory_items enable row level security;alter table public.inventory_transactions enable row level security;alter table public.reviews enable row level security;alter table public.notifications enable row level security;alter table public.audit_logs enable row level security;
grant usage on schema public to anon,authenticated;
grant select,insert,update,delete on all tables in schema public to anon,authenticated;
create policy "profiles read self" on public.profiles for select to authenticated using(id=auth.uid());create policy "profiles update self" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "admins read self" on public.super_admins for select to authenticated using(user_id=auth.uid());
create policy "restaurants public active or member" on public.restaurants for select to anon,authenticated using(status='active' or public.has_restaurant_access(id));create policy "restaurant admin update" on public.restaurants for update to authenticated using(public.has_restaurant_access(id,array['restaurant_owner','manager']::public.member_role[])) with check(public.has_restaurant_access(id,array['restaurant_owner','manager']::public.member_role[]));
create policy "application owner or admin read" on public.restaurant_applications for select to authenticated using(owner_id=auth.uid() or public.is_super_admin());create policy "owner submit application" on public.restaurant_applications for insert to authenticated with check(owner_id=auth.uid() and status='pending' and restaurant_id is null);
create policy "members read own memberships" on public.restaurant_memberships for select to authenticated using(user_id=auth.uid());
create policy "plans public active read" on public.subscription_plans for select to anon,authenticated using(active);
create policy "subscription member read" on public.subscriptions for select to authenticated using(public.has_restaurant_access(restaurant_id));
create policy "categories public read" on public.categories for select to anon,authenticated using(exists(select 1 from public.restaurants r where r.id=restaurant_id and r.status='active'));create policy "categories manager write" on public.categories for all to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[]));
create policy "products public read" on public.products for select to anon,authenticated using(available and exists(select 1 from public.restaurants r where r.id=restaurant_id and r.status='active') or public.has_restaurant_access(restaurant_id));create policy "products manager write" on public.products for all to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[]));
create policy "variants public read" on public.product_variants for select to anon,authenticated using(exists(select 1 from public.products p join public.restaurants r on r.id=p.restaurant_id where p.id=product_id and p.available and r.status='active'));create policy "variants manager write" on public.product_variants for all to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[]));
create policy "tables member read" on public.restaurant_tables for select to authenticated using(public.has_restaurant_access(restaurant_id));create policy "tables manager write" on public.restaurant_tables for all to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','waiter']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','waiter']::public.member_role[]));
create policy "orders customer or restaurant read" on public.orders for select to authenticated using(customer_id=auth.uid() or public.has_restaurant_access(restaurant_id));create policy "staff create order" on public.orders for insert to authenticated with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','waiter']::public.member_role[]));create policy "staff update orders" on public.orders for update to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','kitchen_staff','waiter']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','kitchen_staff','waiter']::public.member_role[]));
create policy "items customer or member read" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (o.customer_id=auth.uid() or public.has_restaurant_access(o.restaurant_id))));create policy "items manager update" on public.order_items for all to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','waiter']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','waiter']::public.member_role[]));
create policy "payments private read" on public.payments for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (o.customer_id=auth.uid() or public.has_restaurant_access(o.restaurant_id))));
create policy "reservations customer or member read" on public.reservations for select to authenticated using(customer_id=auth.uid() or public.has_restaurant_access(restaurant_id));create policy "customer create reservation" on public.reservations for insert to authenticated with check(customer_id=auth.uid() and exists(select 1 from public.restaurants r where r.id=restaurant_id and r.status='active'));create policy "restaurant manage reservations" on public.reservations for update to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','waiter']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager','waiter']::public.member_role[]));
create policy "inventory member read" on public.inventory_items for select to authenticated using(public.has_restaurant_access(restaurant_id));create policy "inventory manager write" on public.inventory_items for all to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[]));create policy "inventory transactions manager" on public.inventory_transactions for all to authenticated using(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[])) with check(public.has_restaurant_access(restaurant_id,array['restaurant_owner','manager']::public.member_role[]));
create policy "reviews public read" on public.reviews for select to anon,authenticated using(true);create policy "customer create review" on public.reviews for insert to authenticated with check(customer_id=auth.uid() and exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid() and o.status='completed'));
create policy "notifications self read" on public.notifications for select to authenticated using(user_id=auth.uid() or public.has_restaurant_access(restaurant_id));create policy "notifications self update" on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "audit owner read" on public.audit_logs for select to authenticated using(restaurant_id is not null and public.has_restaurant_access(restaurant_id,array['restaurant_owner']::public.member_role[]));

insert into public.subscription_plans(name,price,features) values ('Free',0,'["Restaurant workspace","Menu and order basics"]'),('Basic',29,'["Operational reports","Inventory tools"]'),('Premium',79,'["Advanced analytics","Priority support"]') on conflict(name) do nothing;
-- Enable live kitchen updates (safe to omit if already in the publication).
do $$begin alter publication supabase_realtime add table public.orders;exception when duplicate_object then null;when undefined_object then null;end$$;
